@GetMapping("/optimization-actions")
public ResponseEntity<String> getOptimizationActions(HttpServletRequest request) {
    DigitalTwinHouse twin = userService.getDigitalTwin();
    java.util.List<java.util.Map<String, Object>> candidates = new java.util.ArrayList<>();

    if (twin != null) {
        if (Boolean.TRUE.equals(twin.getEvCharger())) {
            candidates.add(java.util.Map.of(
                "id", "opt-ev-1", "title", "Shift EV Charging to Super Off-Peak", "category", "EV Charging",
                "description", "Charge vehicle between 01:00 - 05:00", "base_carbon_delta", -4.2,
                "base_cost_delta", -3.50, "base_ease_score", 95, "base_eco_points", 150
            ));
        }
        if (Boolean.TRUE.equals(twin.getHeatPump())) {
            candidates.add(java.util.Map.of(
                "id", "opt-hp-1", "title", "Pre-cool House Before Peak", "category", "HVAC",
                "description", "Lower thermostat by 2 degrees before 4 PM", "base_carbon_delta", -1.8,
                "base_cost_delta", -1.20, "base_ease_score", 80, "base_eco_points", 50
            ));
        }
    }
    candidates.add(java.util.Map.of(
        "id", "opt-lights-1", "title", "Dim smart lights during peak", "category", "Lighting",
        "description", "Reduce lighting brightness to 50%", "base_carbon_delta", -0.5,
        "base_cost_delta", -0.30, "base_ease_score", 100, "base_eco_points", 20
    ));

    java.util.Map<String, Object> payload = new java.util.HashMap<>();
    payload.put("weights", java.util.Map.of("cost", 1.0, "carbon", 1.0, "comfort", 1.0));
    payload.put("max_actions", 5);
    payload.put("candidates", candidates);

    return proxyService.proxyRequest(request, HttpMethod.POST, payload, "/api/v1/user/optimization-actions");
}

